      "per_unit_profit": "Profit per unit of product i = Sale_Price_Per_Unit[i] - Material_Cost_Per_Unit[i]"
    },
    "constraints": [
      {
        "name": "Molding Capacity Constraint",
        "expression": "Σᵢ Molding_Mins_Req[i] × x[i] ≤ Molding_Capacity_Total",
        "description": "Total molding minutes used across all products must not exceed available molding capacity",
        "csv_column": "Molding_Mins_Req",
        "parameter_to_specify": "Molding_Capacity_Total (total available molding minutes, e.g., per week or per quarter)"
      },
      {
        "name": "Assembly Capacity Constraint",
        "expression": "Σᵢ Assembly_Mins_Req[i] × x[i] ≤ Assembly_Capacity_Total",
        "description": "Total assembly minutes used across all products must not exceed available assembly capacity",
        "csv_column": "Assembly_Mins_Req",
        "parameter_to_specify": "Assembly_Capacity_Total (total available assembly minutes, e.g., per week or per quarter)"
      },
      {
        "name": "Market Demand Constraint",
        "expression": "x[i] ≤ Max_Market_Capacity[i]  for each product i",
        "description": "Production quantity for each product cannot exceed its maximum market capacity",
        "csv_column": "Max_Market_Capacity"
      },
      {
        "name": "Non-negativity Constraint",
        "expression": "x[i] ≥ 0  for each product i",
        "description": "Production quantities cannot be negative"
      }
    ],
    "parameter_mapping": {
      "from_csv": {
        "Sale_Price_Per_Unit": "Revenue per unit for each product (float64, range: 40.68 to 295.77, mean: 112.26)",
        "Material_Cost_Per_Unit": "Material cost per unit for each product (float64, range: 8.85 to 252.69, mean: 65.42)",
        "Molding_Mins_Req": "Molding minutes required per unit for each product (float64, range: 5.1 to 89.3, mean: 23.77)",
        "Assembly_Mins_Req": "Assembly minutes required per unit for each product (float64, range: 11.4 to 59.4, mean: 24.12)",
        "Max_Market_Capacity": "Maximum market capacity per product (int64, range: 110 to 781, mean: 456.88)",
        "Product_SKU": "Unique product identifier (80 distinct SKUs: SKU-0001 to SKU-0080)"
      },
      "to_be_specified_by_planner": {
        "Molding_Capacity_Total": "Total available molding minutes (e.g., based on available molding machines × operating hours × number of periods)",
        "Assembly_Capacity_Total": "Total available assembly minutes (e.g., based on available assembly workers × operating hours × number of periods)",
        "Time_Period": "The planning horizon (e.g., weekly, monthly, quarterly) for which the optimization is performed"
      }
    },
    "additional_context": {
      "number_of_products": 80,
      "data_summary": {
        "avg_profit_margin_per_unit": "Approximately 46.84 (mean Sale_Price 112.26 - mean Material_Cost 65.42)",
        "avg_molding_time_per_unit": "23.77 minutes",
        "avg_assembly_time_per_unit": "24.12 minutes",
        "avg_max_market_capacity": "456.88 units"
      },
      "notes": [
        "The problem is a Linear Programming (LP) problem if x[i] is continuous, or Integer Linear Programming (ILP) if x[i] must be integer.",
        "Supplier_ID and Customer_Rating_Avg are not directly used in the optimization but may inform strategic decisions (e.g., supplier reliability, quality considerations).",
        "Previous_Quarter_Sales can serve as a reference or lower bound for production planning but is not a constraint in the base formulation.",
        "Color_Variant (6 variants) may be relevant for demand forecasting but does not affect the core optimization structure."
      ]
    }
  }
}
